package topology

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const validRecord = `{
  "schemaVersion": 1,
  "generator": {"tool": "Intropy.Topology.Generation", "version": "0.1.0", "source": "integrations@3f9c2e1"},
  "system": {"name": "product-distribution", "owner": "group:default/team-integration", "domain": "distribution"},
  "components": [
    {"name": "pim-extractor", "type": "extractor", "tags": ["int-042"], "project": "pim-extractor",
     "workload": "cronjob", "trigger": {"kind": "schedule", "schedule": "*/15 * * * *"}},
    {"name": "erp-loader", "type": "loader", "tags": ["int-042"], "project": "erp-loader"},
    {"name": "mock-pim", "type": "mock", "lifecycle": "local", "implements": "system:default/pim",
     "profiles": ["local"], "image": "ghcr.io/integrio/mock-pim:1.2.0"}
  ],
  "resources": [
    {"name": "product-raw", "type": "topic", "pubsub": "product-distribution-pubsub", "entity": "RawProduct"},
    {"name": "pim", "type": "connector", "transport": "sftp", "daprComponent": "pim",
     "externalSystem": "system:default/pim"}
  ],
  "apis": [
    {"name": "product-enriched", "type": "asyncapi", "direction": "provides",
     "contract": "Integrio.Contracts.Products", "topic": "resource:product-enriched"}
  ],
  "edges": [
    {"from": "resource:pim", "to": "component:pim-extractor", "kind": "connector"},
    {"from": "component:pim-extractor", "to": "resource:product-raw", "kind": "publish", "port": "default"},
    {"from": "resource:product-raw", "to": "component:erp-loader", "kind": "consume"}
  ]
}`

func writeRecord(t *testing.T, systemDir, body string) string {
	t.Helper()
	dir := filepath.Join(systemDir, ".intropy")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "topology.json")
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

func TestLoadValid(t *testing.T) {
	path := writeRecord(t, t.TempDir(), validRecord)
	got, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if got.System.Name != "product-distribution" || got.System.Owner != "group:default/team-integration" {
		t.Errorf("system = %+v", got.System)
	}
	if got.Generator.Source != "integrations@3f9c2e1" {
		t.Errorf("generator = %+v", got.Generator)
	}
	if len(got.Components) != 3 || len(got.Resources) != 2 || len(got.APIs) != 1 || len(got.Edges) != 3 {
		t.Fatalf("entity counts = %d/%d/%d/%d, want 3/2/1/3",
			len(got.Components), len(got.Resources), len(got.APIs), len(got.Edges))
	}
	if c := got.Components[0]; c.Trigger == nil || c.Trigger.Kind != "schedule" || c.Trigger.Schedule != "*/15 * * * *" {
		t.Errorf("extractor trigger = %+v", c.Trigger)
	}
	if r := got.Resources[1]; r.Type != "connector" || r.DaprComponent != "pim" || r.ExternalSystem != "system:default/pim" {
		t.Errorf("connector = %+v", r)
	}
	if e := got.Edges[1]; e.Kind != "publish" || e.Port != "default" {
		t.Errorf("publish edge = %+v", e)
	}
}

func TestLoadMissing(t *testing.T) {
	_, err := Load(filepath.Join(t.TempDir(), "nope.json"))
	if err == nil {
		t.Fatal("expected error for missing file")
	}
}

func TestLoadMalformed(t *testing.T) {
	path := writeRecord(t, t.TempDir(), "{not json")
	if _, err := Load(path); err == nil || !strings.Contains(err.Error(), "parse topology record") {
		t.Fatalf("err = %v, want parse error", err)
	}
}

// An unknown schema version is surfaced as an error, not guessed at.
