	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "distribution", "product-distribution"), validRecord)
	other := strings.Replace(validRecord, "product-distribution", "order-intake", 1)
	writeRecord(t, filepath.Join(root, "sales", "order-intake"), other)
