	if entries[0].System.Name != "product-distribution" || entries[1].System.Name != "order-intake" {
		t.Errorf("systems = %q, %q", entries[0].System.Name, entries[1].System.Name)
	}
	if want := filepath.Join(root, "distribution", "product-distribution"); entries[0].Path != want {
