// TestTopologyPopulated checks that a system's declared topology record is
// served with its path normalized to the same root-relative identifier the
// integration endpoints use.
func TestTopologyPopulated(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	system := filepath.Join(tmp, "distribution", "product-distribution")
	writeScaffold(t, filepath.Join(system, "pim-extractor"), "extractor", "v0.1.6")
	if err := os.MkdirAll(filepath.Join(system, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	record := `{
  "schemaVersion": 1,
  "generator": {"tool": "Intropy.Topology.Generation"},
  "system": {"name": "product-distribution", "owner": "group:default/team-integration"},
  "components": [{"name": "pim-extractor", "type": "extractor", "project": "pim-extractor"}],
  "resources": [{"name": "product-raw", "type": "topic", "pubsub": "pubsub", "entity": "RawProduct"}],
  "edges": [{"from": "component:pim-extractor", "to": "resource:product-raw", "kind": "publish"}]
}`
	if err := os.WriteFile(filepath.Join(system, ".intropy", "topology.json"), []byte(record), 0o644); err != nil {
		t.Fatal(err)
	}

	rec := get(t, testHandler(t, "."), "/api/topology")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	var entries []map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(entries) != 1 {
		t.Fatalf("entries = %d, want 1", len(entries))
	}
	if entries[0]["path"] != "distribution/product-distribution" {
		t.Errorf("path = %v, want distribution/product-distribution", entries[0]["path"])
	}
	sys, _ := entries[0]["system"].(map[string]any)
	if sys["name"] != "product-distribution" {
		t.Errorf("system = %v", entries[0]["system"])
	}
	comps, _ := entries[0]["components"].([]any)
	if len(comps) != 1 {
		t.Fatalf("components = %v, want 1", entries[0]["components"])
	}
	edges, _ := entries[0]["edges"].([]any)
	if len(edges) != 1 {
		t.Fatalf("edges = %v, want 1", entries[0]["edges"])
	}
}

// TestIntegrationDetailRoot covers an integration scaffolded at the
// workspace root: its identifier is "." but a browser strips that segment,
// so /api/integrations/ (empty path) must resolve to the root integration.
func TestIntegrationDetailRoot(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, tmp, "transactional", "v0.1.6")

	rec := get(t, testHandler(t, "."), "/api/integrations/")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body.String())
	}
	var detail map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &detail); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	if detail["path"] != "." || detail["template"] != "transactional" {
		t.Errorf("unexpected detail: %v", detail)
	}

