  display: inline-flex;
  align-items: center;
  padding: 0 12px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font: inherit;
  font-weight: 500;
  border-bottom: 2px solid transparent;
}

.nav-item:hover {
  color: var(--text);
}

.nav-item.active {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.version {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
  font-size: 12px;
  padding: 3px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
}

